function biggestAfterSwap(num: number): number {
  const s = String(num).split("");
  let best = num;
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j < s.length; j++) {
      [s[i], s[j]] = [s[j], s[i]];
      best = Math.max(best, Number(s.join("")));
      [s[i], s[j]] = [s[j], s[i]];
    }
  }
  return best;
}

