  });
  for (let i = 0; i < s.length; i++) {
    for (let d = 9; d > s[i]; d--) {
      if (last[d] > i) {
        [s[i], s[last[d]]] = [s[last[d]], s[i]];
        return Number(s.join(""));
      }
    }
  }
  return num;
}
